# -*- coding: utf-8 -*-
"""Наполняет content/diffs/*.md отдельными текстами для каждой пары звуков:
вступление, таблица «Чем отличаются», занятия по этапам (вкладки).
Запуск: python tools/seed_diffs.py  (перезаписывает поля intro/compare/stages и текст)."""
import os, re, yaml

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DIR = os.path.join(ROOT, "content", "diffs")

